#!/usr/bin/env bash

# NOTE: Initial file generated by Claude Sonnet 5.5.

# Sourced by generate-config.sh and docker-entrypoint.sh.
#
# load_env_file FILE
#   Reads KEY=VALUE lines (blank lines and "#" comments allowed; values may be
#   wrapped in single or double quotes). The file is parsed, not executed.
#   Variables already present in the environment take precedence over the file.

load_env_file() {
  local file="$1" line key value
  while IFS= read -r line || [ -n "$line" ]; do
    line="${line%$'\r'}"
    case "$line" in ''|'#'*) continue ;; esac
    key="${line%%=*}"
    value="${line#*=}"
    key="${key//[[:space:]]/}"
    [[ "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || continue
    if [[ "$value" =~ ^\"(.*)\"$ ]] || [[ "$value" =~ ^\'(.*)\'$ ]]; then
      value="${BASH_REMATCH[1]}"
    fi
    if [ -z "${!key+x}" ]; then
      export "$key=$value"
    fi
  done < "$file"
}
